/// Claim blocks for the calling client. The result lists each block's owner.
///
/// - When the clients attached to a session want different things for a block, such as a
///   terminal's size, the block follows its owner. Owning a block gives no other rights over it.
/// - The calling client must be attached to the session, with `session.attach` or
///   `session.bootstrap`. A connection that only called `session.attach_all` fails with
///   `bad_request`.
/// - Either mode puts the caller in line for the block. When the owner gives it up, detaches, or
///   loses its connection, the block passes to the connected client in line that claimed it most
///   recently, with any `take` ahead of every `request`.
/// - An owner whose connection drops gets each of its blocks back when it reconnects, unless that
///   block's owner has changed again since.
/// - `blocks` lists each block's owner after the call, in the order of `block_ids`, with a
///   repeated ID listed once. When you claim every block, they are sorted by `block_id`.
/// - Every change of owner sends `block_owner_changed`. If a block in a window changes owner, the
///   call also sends one `session_view_changed`, because `session.view` shows owners.
/// - A `mode` other than `take` or `request` fails with `bad_request`.
/// - If any ID in `block_ids` isn't a block in the session, the call fails with `bad_request` and
///   changes nothing.
///
/// Wire method: `session.own_block`.
///
/// # Example
///
/// ```json
/// {
///   "session_id": "session:<uuid>",
///   "block_ids": ["block:<uuid>"],
///   "mode": "request"
/// }
/// ```
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize, Default)]
#[non_exhaustive]
pub struct OwnBlock {
    /// The session to act on.
    pub session_id: String,
    /// The blocks to claim. Leave it out or empty to claim every block in the session.
    #[serde(
        default,
        deserialize_with = "crate::api::nullable",
        skip_serializing_if = "Vec::is_empty"
    )]
    pub block_ids: Vec<Option<String>>,
    /// How to claim them. 'take' makes the calling client the owner right away. 'request' makes it
    /// the owner only of blocks that have none, and it may get the rest when their owner gives them
    /// up or leaves. Defaults to take.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mode: Option<String>,
}

impl OwnBlock {
    /// Creates a `OwnBlock` with its required fields.
    pub fn new(session_id: impl Into<String>) -> Self {
        Self {
            session_id: session_id.into(),
            block_ids: Default::default(),
            mode: Default::default(),
        }
    }

    /// The blocks to claim. Leave it out or empty to claim every block in the session.
    pub fn block_ids(mut self, value: impl IntoIterator<Item = Option<String>>) -> Self {
        self.block_ids = value.into_iter().collect();
        self
    }

    /// How to claim them. 'take' makes the calling client the owner right away. 'request' makes it
    /// the owner only of blocks that have none, and it may get the rest when their owner gives them
    /// up or leaves. Defaults to take.
    pub fn mode(mut self, value: impl Into<String>) -> Self {
        self.mode = Some(value.into());
        self
    }
}

